import{_ as e,o,c as r,a}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const m=JSON.parse('{"title":"Как я доделал все пет-проекты и работаю с 10 млн строк кода","description":"","frontmatter":{"site":"pro","title":"Как я доделал все пет-проекты и работаю с 10 млн строк кода","date":"2026-09-15T00:00:00.000Z","source":"https://t.me/jfyi_ps/85","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-09-15-kak-ya-dodelal-vse-pet-proekty-i"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Как я доделал все пет-проекты и работаю с 10 млн строк кода"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-09-15-kak-ya-dodelal-vse-pet-proekty-i"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Как я доделал все пет-проекты и работаю с 10 млн строк кода"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Как я доделал все пет-проекты и работаю с 10 млн строк кода\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-09-15-kak-ya-dodelal-vse-pet-proekty-i\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-09-15\\"}"]]},"headers":[],"relativePath":"posts/2026-09-15-kak-ya-dodelal-vse-pet-proekty-i.md","filePath":"posts/2026-09-15-kak-ya-dodelal-vse-pet-proekty-i.md"}'),n={name:"posts/2026-09-15-kak-ya-dodelal-vse-pet-proekty-i.md"};function p(s,t,i,l,d,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<p>Подход работает с любыми агентно-ориентированными LLM — DeepSeek, Claude, GLM и т.п.</p><p><strong>1. Архитектура — один раз.</strong> Фиксирую CJM, бизнес-требования, контракты между компонентами, доменную модель, потоки данных, безопасность. Без бизнес-требований нет системного дизайна. Это фундамент и «память о проекте» для ИИ-агента. Занимает 1–2 недели проб и ошибок.</p><p><strong>2. План вместо разрастающихся спецификаций.</strong> Спецификации на больших проектах сами становятся проблемой. План не разрастается: выполнил — в архив. Зачем держать спецификацию, если уже есть код? Планирование — самое трудоёмкое: план нужно перечитать несколько раз и убедиться, что нейросеть поняла правильно.</p><p><strong>3. Запуск плана.</strong> Специальная утилита, написанная на Go берёт последний невыполненный пункт и выполняет его. Обычно хватает одной сессии; иногда каждому пункту нужен свой контекст. Выполнение переживает обрыв сессии и продолжает с последнего невыполненного пункта.</p><p><strong>4. Код-ревью — самый затратный этап.</strong> Когда план выполнен и тесты зелёные, запускаю 5–9 агентов. Они смотрят код через разные призмы. Результат идёт в агент-синтезатор: убирает дубли и выдаёт список. Потом агенты другой нейросети верифицируют находки. На моих задачах это даёт очень качественный код — сужу как эксперт с 8-летним стажем ревью.</p><p><strong>5. Ручная верификация или автопилот.</strong> Обычно проверяю руками. В сложных системах писал нейросеть-автопилота, которая проходит по системе и принимает решения по ситуации. Это полезно там, где сложный мир, роли и права, фичи, которые в итоге тестируют конечные пользователи.</p><p>PS: Чтобы не собирать промпт для плана вручную из многих источников, я сделал KB — RAG-систему, объединяющую знания из чатов, кода, документации и задач. Первая версия была на LangChain/ChromaDB (Python), потом переписал на Go ради стабильности и скорости. Код: <a href="https://github.com/alterfo/kb" target="_blank" rel="noreferrer">https://github.com/alterfo/kb</a></p><p>А вы как организуете работу LLM-агентов? Что пробовали?</p>',8)])])}const k=e(n,[["render",p]]);export{m as __pageData,k as default};
